-- Eleven named workflows; property geocoding preserves one address per subject.
BEGIN;
ALTER TABLE gateway_v2.workflow_runs DROP CONSTRAINT IF EXISTS workflow_runs_status_check;
ALTER TABLE gateway_v2.workflow_runs ADD CONSTRAINT workflow_runs_status_check CHECK(status IN ('quoted','needs_input','needs_selection','unsupported','running','completed','partial','failed','cancelled'));
ALTER TABLE gateway_v2.workflow_runs DROP CONSTRAINT IF EXISTS workflow_runs_workflow_slug_check;
ALTER TABLE gateway_v2.workflow_runs ADD CONSTRAINT workflow_runs_workflow_slug_check CHECK(workflow_slug IN ('supplier-payment-check','prospect-shortlist','customer-onboarding','competitor-comparison','tender-finder','subsidy-finder','property-precheck','company-ownership','company-health','vehicle-precheck','company-news'));

